def smallest_subcover(intervals, a, b):
    """Sorted indices of a smallest subcover of [a, b] by open intervals, or None."""
    chosen = []
    x = a
    while True:
        best = None
        for k, (lo, hi) in enumerate(intervals):
            if lo < x < hi and (best is None or hi > intervals[best][1]):
                best = k
        if best is None:
            return None       # x lies in no interval: a gap
        chosen.append(best)
        x = intervals[best][1]
        if x > b:
            return sorted(chosen)
